import{_ as i,l as n,o as a,c as s,v as o,p as d,x as t,d as l,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const L=JSON.parse('{"title":"外连接与半连接","description":"","frontmatter":{"title":"外连接与半连接","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/outer-semi-join.md","filePath":"cs/outer-semi-join.md","lastUpdated":1789023840000}'),p={name:"cs/outer-semi-join.md"};function h(A,e,m,_,u,B){const r=n("Mermaid");return a(),s("div",null,[e[1]||(e[1]=o('<h1 id="外连接与半连接" tabindex="-1">外连接与半连接 <a class="header-anchor" href="#外连接与半连接" aria-label="Permalink to &quot;外连接与半连接&quot;">​</a></h1><div class="epigraph"><p>内连接丢掉未匹配行；外连接把它们留下并填 NULL。半连接只保留左侧中那些在右侧找得到伙伴的行，不展开右侧列。</p><footer>—— 据 Date 对外连接；Ramakrishnan and Gehrke 对半连接；Bernstein and Chiu 对半连接归约</footer></div><p><a href="/cs/set-ops-exists">上一课</a>用差与 <code>NOT EXISTS</code> 表达「没有伙伴」。本课不重写反半连接的三值缝。缺口是连接族里另外两支：<strong>外连接</strong>（保留未匹配并补 NULL）与<strong>半连接</strong>（测试存在但不把右侧列并进结果）。主干 <a href="/cs/join-algorithms">连接算法</a> 讲内连接三种形状；进阶要把这两种逻辑算子钉进树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「列出所有顾客及其订单，没有订单的顾客也要一行」——内连接会丢掉无单顾客。左外连接保留左表全部，右无匹配则订单列 NULL。全外连接两侧未匹配都留。缺口不是语法 <code>LEFT JOIN</code>，而是：NULL 填充使若干代数律失效，<a href="/cs/predicate-pushdown">谓词下推</a> 必须停在外连接边界，除非谓词拒绝 NULL 的方式与填充后一致。</p><p>半连接 \\(R \\ltimes S\\)：结果模式等于 \\(R\\)，行是 \\(R\\) 中至少有一条 \\(S\\) 匹配的那些（包语义下计数规则要写清：通常按 \\(R\\) 的包，不按匹配条数膨胀）。它实现 <code>EXISTS</code>/<code>IN</code>。反半连接实现 <code>NOT EXISTS</code>。分布式后课会用半连接压缩传送列；本课只锁定单机指称。</p><p><span class="marginnote">Bernstein and Chiu 的半连接用于分布式查询：先传键再传匹配元组。逻辑上半连接仍是「存在测试」。外连接不是半连接加 NULL 的随便组合：全外连接要两侧补洞。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>逻辑树节点：inner / left / right / full / semi / anti-semi。物理上外连接在哈希或归并时多一条「未探测到则吐 NULL 行」的路径；嵌套循环左外连接对外层每行至少吐一次。半连接可在探测成功后对当前左行停止展开右侧。</p><p>谓词放在 <code>ON</code> 还是外连接之后的 <code>WHERE</code>：后者会把外连接补的 NULL 行再滤掉，常把左外连接打回内连接。这是语义，优化器可以识别并改写，但用户写错就是指称变了。</p>',10)),(a(),d(c,null,{default:t(()=>[E(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20INJ%5B%22%E5%86%85%E8%BF%9E%E6%8E%A5%22%5D%20--%3E%20DROP%5B%22%E4%B8%A2%E6%9C%AA%E5%8C%B9%E9%85%8D%22%5D%0A%20%20OJ%5B%22%E5%A4%96%E8%BF%9E%E6%8E%A5%22%5D%20--%3E%20PAD%5B%22%E7%95%99%E8%A1%8C%E5%A1%AB%20NULL%22%5D%0A%20%20SJ%5B%22%E5%8D%8A%E8%BF%9E%E6%8E%A5%22%5D%20--%3E%20KEEP%5B%22%E5%8F%AA%E7%95%99%E5%B7%A6%E4%BE%A7%E5%AD%98%E5%9C%A8%E8%A1%8C%22%5D%0A%20%20ASJ%5B%22%E5%8F%8D%E5%8D%8A%E8%BF%9E%E6%8E%A5%22%5D%20--%3E%20ABS%5B%22%E5%8F%AA%E7%95%99%E5%B7%A6%E4%BE%A7%E6%97%A0%E5%8C%B9%E9%85%8D%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>改写：内连接上的选择可分到两侧；外连接的 <code>ON</code> 谓词不能随意变成连接后过滤。半连接与内连接再投影在无重复匹配时同指称，有重复时内连接膨胀行数、半连接不膨胀——这正是 <code>EXISTS</code> 与「连接再 DISTINCT」的差别。</p><p>优化器可以把 <code>IN</code> 当半连接，把「连接后只取左列」收缩成半连接。代价模型按左表基数而不是积的基数估输出。直方图仍来自主干 <a href="/cs/histogram-card">基数</a>，本课不重做桶。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲连接顺序枚举里外连接如何限制交换——后课 Selinger 与连接树会碰到外连接不能随便换结合括号。也不把 NULL 填充当成缺失值的统计模型。</p><p>后课默认：要保留未匹配用外连接；要存在测试用半连接，不要先 inner join 再去重。约束与触发器下一课：完整性是写路径上的断言，不是连接种类。</p><p>外连接改变结果模式里的 NULL 位置；半连接不改变左侧模式。两者都不是「一种更快的内连接」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>外连接保留未匹配并填 NULL，挡住部分下推。</li><li>半连接实现存在量化，不膨胀、不带右列。</li><li><code>WHERE</code> 写在外连接之后可能取消外连接。</li><li>出处：Date；Ramakrishnan and Gehrke；Bernstein and Chiu。</li></ul>',9))])}const S=i(p,[["render",h]]);export{L as __pageData,S as default};
